/**
 * Facebook Ads AI Draft Service
 * 
 * Manages multi-angle Facebook ad drafts generated by the AI agent,
 * persists them to the PostgreSQL database, and prepares them for
 * safe one-click publishing via Meta Marketing API v25.0.
 */

const crypto = require('crypto');
const { getSharedPrismaClient } = require('./sharedDatabase');

function safeParseJson(value, fallback = {}) {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

class FacebookAdsAiDraftService {
  constructor() {
    this._prisma = null;
  }

  get prisma() {
    if (!this._prisma) {
      this._prisma = getSharedPrismaClient();
    }
    return this._prisma;
  }

  /**
   * Create an AI Draft Run with multiple creative angles
   */
  async createDraftRun({
    companyId,
    userId = null,
    productUrl,
    productSnapshot = null,
    adAccountId = null,
    pageId = null,
    pixelId = null,
    budgetAmount = 200,
    targetCountry = 'EG',
    targetGenders = 'ALL',
    ageMin = 18,
    ageMax = 45,
    angles = [],
  }) {
    if (!companyId) throw new Error('companyId is required');
    if (!productUrl) throw new Error('productUrl is required');
    if (!Array.isArray(angles) || angles.length === 0) {
      throw new Error('At least one ad angle is required');
    }

    const inputHash = crypto
      .createHash('sha256')
      .update(`${companyId}:${productUrl}:${angles.length}:${Date.now()}`)
      .digest('hex');

    const run = await this.prisma.facebookAdsAiDraftRun.create({
      data: {
        companyId,
        userId,
        inputHash,
        productUrl,
        productSnapshot: typeof productSnapshot === 'object' ? JSON.stringify(productSnapshot) : productSnapshot,
        adAccountId,
        pageId,
        pixelId,
        requestedCampaignCount: angles.length,
        budgetAmount: Number(budgetAmount) || 200,
        targetCountry: targetCountry || 'EG',
        targetGenders: targetGenders || 'ALL',
        ageMin: Number(ageMin) || 18,
        ageMax: Number(ageMax) || 45,
        status: 'COMPLETED',
        drafts: {
          create: angles.map((angle, index) => {
            const fullAdData = {
              productUrl,
              campaignName: angle.campaignName || angle.campaign_name || `AI Campaign - Angle ${index + 1}`,
              objective: 'OUTCOME_SALES',
              status: 'PAUSED',
              adSetName: angle.adSetName || angle.adset_name || `AI AdSet - ${angle.angle || 'Targeting'}`,
              budget: Number(angle.budgetAmount || angle.budget_amount || budgetAmount) || 200,
              country: angle.targetCountry || angle.target_country || targetCountry || 'EG',
              ageMin: Number(angle.ageMin || angle.age_min || ageMin) || 18,
              ageMax: Number(angle.ageMax || angle.age_max || ageMax) || 45,
              genders: angle.targetGenders || angle.target_genders || targetGenders || 'ALL',
              adName: angle.adName || angle.ad_name || `AI Ad - ${angle.headline || 'Creative'}`,
              primaryText: angle.primaryText || angle.primary_text || '',
              headline: angle.headline || '',
              description: angle.description || '',
              callToAction: angle.callToAction || angle.call_to_action || 'SHOP_NOW',
              imageUrl: angle.imageUrl || angle.image_url || null,
              pixelId: pixelId || angle.pixelId || angle.pixel_id || null,
              conversionEvent: angle.conversionEvent || angle.conversion_event || 'PURCHASE',
              conversionLocation: 'WEBSITE',
              performanceGoal: 'MAXIMIZE_CONVERSIONS',
              optimizationGoal: 'OFFSITE_CONVERSIONS',
              advantagePlusPlacements: true,
              advantagePlusAudience: true,
            };

            return {
              companyId,
              userId,
              productUrl,
              productSnapshot: typeof productSnapshot === 'object' ? JSON.stringify(productSnapshot) : productSnapshot,
              index: index + 1,
              angle: angle.angle || `angle_${index + 1}`,
              campaignName: fullAdData.campaignName,
              adSetName: fullAdData.adSetName,
              adName: fullAdData.adName,
              primaryText: fullAdData.primaryText,
              headline: fullAdData.headline,
              description: fullAdData.description,
              callToAction: fullAdData.callToAction,
              budgetAmount: fullAdData.budget,
              targetCountry: fullAdData.country,
              targetGenders: fullAdData.genders,
              ageMin: fullAdData.ageMin,
              ageMax: fullAdData.ageMax,
              notes: angle.notes || null,
              createFullAdData: JSON.stringify(fullAdData),
              status: 'DRAFT',
            };
          }),
        },
      },
      include: {
        drafts: true,
      },
    });

    return run;
  }

  /**
   * Get draft run by ID with its drafts
   */
  async getDraftRun(companyId, runId) {
    return this.prisma.facebookAdsAiDraftRun.findFirst({
      where: {
        id: runId,
        companyId,
      },
      include: {
        drafts: {
          orderBy: { index: 'asc' },
        },
      },
    });
  }

  /**
   * List draft runs for a company
   */
  async listDraftRuns(companyId, limit = 10) {
    return this.prisma.facebookAdsAiDraftRun.findMany({
      where: { companyId },
      include: {
        drafts: true,
      },
      orderBy: { createdAt: 'desc' },
      take: Math.min(Number(limit) || 10, 50),
    });
  }

  /**
   * Get specific draft
   */
  async getDraftById(companyId, draftId) {
    return this.prisma.facebookAdsAiDraft.findFirst({
      where: {
        id: draftId,
        companyId,
      },
      include: {
        run: true,
      },
    });
  }

  /**
   * Prepare validated publish payload for an AI draft
   */
  preparePublishPayload(draft, overrides = {}) {
    const rawData = safeParseJson(draft.createFullAdData, {});
    const rawBudget = Number(overrides.budgetAmount || overrides.budget || draft.budgetAmount || rawData.budgetAmount || rawData.budget) || 200;
    const budgetVal = Math.max(200, rawBudget);
    const destUrl = overrides.linkUrl || overrides.productUrl || draft.productUrl || rawData.productUrl || rawData.linkUrl || '';

    // 🛡️ Auto-hydrate product image from snapshot or draft data
    const snapshot = safeParseJson(draft.productSnapshot, {});
    let imgUrl = overrides.imageUrl || draft.imageUrl || rawData.imageUrl || snapshot.imageUrl || snapshot.mainImage || null;

    if (!imgUrl && Array.isArray(snapshot.images) && snapshot.images.length > 0) {
      imgUrl = snapshot.images[0];
    }

    // Ensure image URL is an absolute URL if relative path provided
    if (typeof imgUrl === 'string' && imgUrl.startsWith('/')) {
      try {
        if (destUrl && destUrl.startsWith('http')) {
          const parsedDest = new URL(destUrl);
          imgUrl = `${parsedDest.origin}${imgUrl}`;
        }
      } catch (_) {}
    }

    const payload = {
      ...rawData,
      ...overrides,
      clientRequestId: overrides.clientRequestId || `ai_draft_pub_${draft.id}_${Date.now()}`,
      campaignName: overrides.campaignName || draft.campaignName || rawData.campaignName,
      adSetName: overrides.adSetName || draft.adSetName || rawData.adSetName,
      adName: overrides.adName || draft.adName || rawData.adName,
      primaryText: overrides.primaryText || draft.primaryText || rawData.primaryText,
      headline: overrides.headline || draft.headline || rawData.headline,
      description: overrides.description !== undefined ? overrides.description : (draft.description || rawData.description),
      budget: budgetVal,
      budgetAmount: budgetVal,
      budgetType: overrides.budgetType || rawData.budgetType || 'DAILY',
      country: overrides.country || draft.targetCountry || rawData.country || 'EG',
      callToAction: overrides.callToAction || draft.callToAction || rawData.callToAction || 'SHOP_NOW',
      status: overrides.status || 'PAUSED', // default PAUSED for safety
      linkUrl: destUrl,
      productUrl: destUrl,
      creativeType: overrides.creativeType || rawData.creativeType || 'SINGLE_IMAGE',
      imageUrl: imgUrl,
      pixelId: overrides.pixelId || rawData.pixelId || draft.pixelId || null,
      conversionEvent: overrides.conversionEvent || rawData.conversionEvent || 'PURCHASE',
      conversionLocation: overrides.conversionLocation || rawData.conversionLocation || 'WEBSITE',
      performanceGoal: overrides.performanceGoal || rawData.performanceGoal || 'MAXIMIZE_CONVERSIONS',
      optimizationGoal: overrides.optimizationGoal || rawData.optimizationGoal || 'OFFSITE_CONVERSIONS',
    };

    return payload;
  }

  /**
   * Mark draft as published with returned Meta identifiers
   */
  async markDraftPublished(companyId, draftId, {
    facebookCampaignId,
    facebookAdSetId,
    facebookAdId,
    facebookCreativeId = null,
  }) {
    return this.prisma.facebookAdsAiDraft.update({
      where: { id: draftId },
      data: {
        status: 'PUBLISHED',
        publishedAt: new Date(),
        facebookCampaignId: String(facebookCampaignId || ''),
        facebookAdSetId: String(facebookAdSetId || ''),
        facebookAdId: String(facebookAdId || ''),
        facebookCreativeId: facebookCreativeId ? String(facebookCreativeId) : null,
      },
    });
  }
}

module.exports = new FacebookAdsAiDraftService();
